import manifest from "@/content/models-manifest.json";
import type { Locale } from "@/lib/types";

/**
 * Typed access to the model gallery (src/content/models-manifest.json, generated by scripts/build-model-art.ts).
 * The originals are never served: each model has renders, a spin sheet and two GLB levels.
 */
export type ModelCategory = "apparel" | "furniture" | "product" | "character" | "creature" | "vehicle" | "prop" | "architecture" | "sculpture";

export type ModelImage = { src: string; srcSmall: string; thumb: string; width: number; height: number };

export type GalleryModel = {
  id: string;
  slug: string;
  name: Record<Locale, string>;
  alt: Record<Locale, string>;
  category: ModelCategory;
  tags: string[];
  /** Set for models that stand for a connection (Shopify, Unity, Blender). They appear only in the connections section. */
  role?: "integration";
  integration?: string;
  colour: string;
  tris: { original: number; web: number; card: number };
  bytes: { web: number; card: number; spin: number; beauty: number; poster: number };
  beauty: ModelImage;
  spin: { src: string; frames: number; cols: number; frameWidth: number; frameHeight: number };
  poster: string;
  glb: { web: string; card: string };
};

export const models = manifest as unknown as GalleryModel[];

/** The gallery proper: everything except the models that illustrate a connection. */
export const galleryModels = models.filter((m) => m.role !== "integration");
export const integrationModels = models.filter((m) => m.role === "integration");

export function getModel(slug: string): GalleryModel | undefined {
  return models.find((m) => m.slug === slug);
}

export function modelsIn(category: ModelCategory): GalleryModel[] {
  return galleryModels.filter((m) => m.category === category);
}

/**
 * Which GLB a live viewer should load: the light one when the visitor asked to save data or has little memory,
 * the standard one otherwise. `deviceMemory` and `saveData` come from the browser (undefined on the server).
 */
export function pickGlb(model: GalleryModel, hints: { saveData?: boolean; deviceMemory?: number; width?: number } = {}): string {
  const light = hints.saveData || (hints.deviceMemory !== undefined && hints.deviceMemory < 4) || (hints.width !== undefined && hints.width < 480);
  return light ? model.glb.card : model.glb.web;
}

/** `2.0M → 60K tris` for the technical line under a model. */
export function trisLine(model: GalleryModel): string {
  const short = (n: number) => (n >= 9.5e5 ? `${(n / 1e6).toFixed(1)}M` : `${Math.round(n / 1e3)}K`);
  return `${short(model.tris.original)} → ${short(model.tris.web)} tris`;
}
